arguments.command:
python3 -c "
import requests
import json

# Try to get IMF WEO data via SDMX API for Georgia
# First, let's try to get the available series
try:
    # Get available countries
    url = 'https://dataservices.imf.org/REST/SDMX_JSON.svc/CodeList/WEO/CL_INDICATOR_WEO'
    response = requests.get(url)
    print('Status code:', response.status_code)

    if response.status_code == 200:
        data = response.json()
        print('Keys:', list(data.keys()))
        if 'Structure' in data and 'CodeLists' in data['Structure']:
            for codelist in data['Structure']['CodeLists']:
                if 'ID' in codelist and codelist['ID'] == 'CL_INDICATOR_WEO':
                    print('GDP indicators found:')
                    for code in codelist['Code']:
                        if 'GDP' in code['@value'] or 'NGDP' in code['@value']:
                            print(code['@value'], '-', code.get('Description', {}).get('#text', ''))
except Exception as e:
    print('Error:', e)
    import traceback
    traceback.print_exc()
"

